commandLine.original:
docker exec -i forkity-v3-db-1 psql -U forkity -d forkity -v ON_ERROR_STOP=1 <<'SQL'
BEGIN;
DO $$
DECLARE
  user_a integer;
  user_b integer;
BEGIN
  INSERT INTO users (email, password_hash)
  VALUES ('migration-check@example.com', 'test')
  RETURNING id INTO user_a;

  BEGIN
    INSERT INTO users (email, password_hash)
    VALUES ('MIGRATION-CHECK@EXAMPLE.COM', 'test');
    RAISE EXCEPTION 'case-insensitive email uniqueness missing';
  EXCEPTION WHEN unique_violation THEN
    NULL;
  END;

  INSERT INTO users (email, password_hash)
  VALUES ('migration-check-other@example.com', 'test')
  RETURNING id INTO user_b;

  INSERT INTO bookmarks (user_id, recipe_id, recipe_data)
  VALUES (user_a, 'shared-recipe', '{"id":"shared-recipe"}'::jsonb);

  BEGIN
    INSERT INTO bookmarks (user_id, recipe_id, recipe_data)
    VALUES (user_a, 'shared-recipe', '{"id":"shared-recipe"}'::jsonb);
    RAISE EXCEPTION 'per-user bookmark uniqueness missing';
  EXCEPTION WHEN unique_violation THEN
    NULL;
  END;

  INSERT INTO bookmarks (user_id, recipe_id, recipe_data)
  VALUES (user_b, 'shared-recipe', '{"id":"shared-recipe"}'::jsonb);

  DELETE FROM users WHERE id = user_a;
  IF EXISTS (SELECT 1 FROM bookmarks WHERE user_id = user_a) THEN
    RAISE EXCEPTION 'bookmark cascade delete missing';
  END IF;
END $$;
ROLLBACK;
SQL

