const request = async (path, payload) => {
  const response = await fetch(`${origin}/api/v1/auth/${path}`, {
    method: payload ? 'POST' : 'GET',
    headers: {
      ...(payload && { 'content-type': 'application/json' }),
      ...(cookie && { cookie }),
    },
    ...(payload && { body: JSON.stringify(payload) }),
  });
  const setCookie = response.headers.getSetCookie()[0];
  if (setCookie) cookie = setCookie.split(';')[0];
  return { response, data: response.status === 204 ? null : await response.json(), setCookie };
};

try {
  const html = await (await fetch(origin)).text();
  assert.match(html, /nav__btn--account/);
  assert.match(html, /Create account/);
  const registered = await request('register', {
    email,
    password: 'A-long-proxy-test-password',
  });
  assert.equal(registered.response.status, 201);
  assert.match(registered.setCookie, /HttpOnly/i);
  assert.equal((await request('me')).data.user.email, email);
  assert.equal((await request('logout', {})).response.status, 204);
  console.log('Frontend/API proxy passed: account UI served, registration cookie is HttpOnly, session is recognized, logout succeeds.');
} finally {
  await pool.query('DELETE FROM users WHERE email = $1', [email]);
  await pool.end();
}
